// Process data and prepare results
const items = $input.all();
if (items.length < 20) {
  throw new Error(`Only ${items.length} rows — need ~20+ to build a useful summary.`);
}

// -------- Bucket rows per room --------
const perRoom = new Map();
const allTimestamps = [];

for (const { json: row } of items) {
  const ts = new Date(row.timestamp);
  if (isNaN(ts.getTime())) continue;
  const t = +row.temperature, h = +row.humidity;
  if (!Number.isFinite(t) || !Number.isFinite(h)) continue;
  const room = +row.room_id;
  if (!perRoom.has(room)) perRoom.set(room, []);
  perRoom.get(room).push({ ts, t, h });
  allTimestamps.push(ts);
}

if (perRoom.size === 0) {
  throw new Error("No valid rows. Check upstream items have timestamp, room_id, temperature, humidity.");
}

// -------- Helpers --------
function mean(a)     { return a.reduce((s,x) => s+x, 0) / a.length; }
function std(a)      { const m = mean(a); return Math.sqrt(mean(a.map(x => (x-m)*(x-m)))); }
function quantile(a, q) {
  const s = [...a].sort((x,y) => x-y);
  const i = (s.length - 1) * q;
  const lo = Math.floor(i), hi = Math.ceil(i);
  return lo === hi ? s[lo] : s[lo] + (s[hi] - s[lo]) * (i - lo);
}
function round(x, d=2) { return Number(x.toFixed(d)); }

// -------- Per-room summary --------
const summary = {};
for (const [room, rows] of perRoom.entries()) {
  rows.sort((a,b) => a.ts - b.ts);
  const temps = rows.map(r => r.t);
  const hums  = rows.map(r => r.h);

  // Monthly aggregates
  const byMonth = {};
  for (const r of rows) {
    const key = `${r.ts.getUTCFullYear()}-${String(r.ts.getUTCMonth()+1).padStart(2,"0")}`;
    if (!byMonth[key]) byMonth[key] = { t: [], h: [] };
    byMonth[key].t.push(r.t);
    byMonth[key].h.push(r.h);
  }
  const monthlyStats = {};
  for (const [k, v] of Object.entries(byMonth)) {
    monthlyStats[k] = {
      n: v.t.length,
      temp_mean: round(mean(v.t)),
      temp_std:  round(std(v.t)),
      hum_mean:  round(mean(v.h)),
      hum_std:   round(std(v.h)),
    };
  }

  // Hour-of-day profile (24 buckets)
  const byHour = Array.from({length: 24}, () => ({t: [], h: []}));
  for (const r of rows) {
    const h = r.ts.getUTCHours();
    byHour[h].t.push(r.t);
    byHour[h].h.push(r.h);
  }
  const hourlyProfile = byHour.map((b, h) => ({
    hour: h,
    n: b.t.length,
    temp_mean: b.t.length ? round(mean(b.t)) : null,
    hum_mean:  b.h.length ? round(mean(b.h)) : null,
  })).filter(b => b.n > 0);

  summary[String(room)] = {
    n_samples: rows.length,
    date_range: { start: rows[0].ts.toISOString(), end: rows[rows.length-1].ts.toISOString() },
    temperature: {
      mean:   round(mean(temps)),
      std:    round(std(temps)),
      min:    round(Math.min(...temps)),
      max:    round(Math.max(...temps)),
      p10:    round(quantile(temps, 0.10)),
      p50:    round(quantile(temps, 0.50)),
      p90:    round(quantile(temps, 0.90)),
    },
    humidity: {
      mean:   round(mean(hums)),
      std:    round(std(hums)),
      min:    round(Math.min(...hums)),
      max:    round(Math.max(...hums)),
      p10:    round(quantile(hums, 0.10)),
      p50:    round(quantile(hums, 0.50)),
      p90:    round(quantile(hums, 0.90)),
    },
    monthly: monthlyStats,
    hourly_profile: hourlyProfile,
  };
}

allTimestamps.sort((a,b) => a-b);

const model = {
  schema: "llm-context-v1",
  target: "both",
  trained_at: new Date().toISOString(),
  note: "This is not a fitted model. It is a statistical digest used as context for an LLM predictor.",
  rooms: Array.from(perRoom.keys()).sort((a,b) => a-b),
  data_range: {
    start: allTimestamps[0].toISOString(),
    end:   allTimestamps[allTimestamps.length - 1].toISOString(),
  },
  summary,
};

// Mirror the previous training node's behaviour so nothing downstream breaks.
const staticData = $getWorkflowStaticData("global");
staticData.temperatureModel = model;

return [{ json: { model } }];

// Process data and prepare results
function resolveModel() {
  const item = $input.item.json;
  if (item && item.model && item.model.schema === "llm-context-v1") return item.model;
  try {
    const sd = $getWorkflowStaticData("global");
    if (sd && sd.temperatureModel && sd.temperatureModel.schema === "llm-context-v1") {
      return sd.temperatureModel;
    }
  } catch (_) {}
  throw new Error(
    "No LLM-context bundle available. Run the training workflow first so the " +
    "statistical summary is written to workflow static data."
  );
}

const item = $input.item.json;
const model = resolveModel();

if (!item.date)    throw new Error("Missing `date` on input item.");
if (item.room_id == null) throw new Error("Missing `room_id` on input item.");
const target = new Date(item.date);
if (isNaN(target.getTime())) throw new Error(`Invalid date: ${item.date}`);

const room = +item.room_id;
const roomKey = String(room);
if (!(roomKey in model.summary)) {
  throw new Error(`Unknown room_id ${room}. Trained on: ${model.rooms.join(", ")}`);
}

const s = model.summary[roomKey];

// --- Build a compact, structured context the LLM can pattern-match on ---

const monthlyLines = Object.entries(s.monthly)
  .sort(([a],[b]) => a.localeCompare(b))
  .map(([mo, v]) =>
    `  ${mo}: temp ${v.temp_mean}°C (±${v.temp_std}), hum ${v.hum_mean}% (±${v.hum_std}), n=${v.n}`
  ).join("\n");

const hourlyLines = s.hourly_profile
  .map(b => `  ${String(b.hour).padStart(2,"0")}h: ${b.temp_mean}°C, ${b.hum_mean}%`)
  .join("\n");

const targetMonth = `${target.getUTCFullYear()}-${String(target.getUTCMonth()+1).padStart(2,"0")}`;
const targetHour  = target.getUTCHours();
const targetDay   = target.toISOString().slice(0, 10);
const trainingEnd = new Date(model.data_range.end);
const daysPast    = Math.round(Math.max(0, (target - trainingEnd) / 86400000));

const system = [
  "You are a time-series predictor for indoor climate sensors.",
  "Given statistical context about a room's temperature and humidity, you estimate the most likely reading at a specific date and time.",
  "You respond ONLY with valid JSON in the exact shape: {\"temperature\": <number>, \"humidity\": <number>, \"reasoning\": \"<one short sentence>\"}.",
  "Do not wrap the JSON in markdown, code fences, or prose. No preamble, no explanation outside the JSON.",
  "Temperatures are in °C; humidity is a percentage 0–100. Round to one decimal place.",
].join("\n");

const user = [
  `# Task`,
  `Predict temperature and humidity for Room ${room} at ${target.toISOString()}.`,
  ``,
  `# Context`,
  `Training data date range: ${model.data_range.start} to ${model.data_range.end}`,
  `This target is ${daysPast} day(s) past the end of training.`,
  `The target falls in month ${targetMonth} at hour ${targetHour} UTC.`,
  ``,
  `# Overall stats for Room ${room} (${s.n_samples} samples)`,
  `Temperature — mean ${s.temperature.mean}°C, std ${s.temperature.std}, range ${s.temperature.min}–${s.temperature.max}°C, median ${s.temperature.p50}°C`,
  `Humidity    — mean ${s.humidity.mean}%, std ${s.humidity.std}, range ${s.humidity.min}–${s.humidity.max}%, median ${s.humidity.p50}%`,
  ``,
  `# Monthly profile for Room ${room}`,
  monthlyLines,
  ``,
  `# Hour-of-day profile for Room ${room}`,
  hourlyLines,
  ``,
  `# Instructions`,
  `1. Look up the training month that best matches the target month (${targetMonth}). If the target is past the end of training, extrapolate using the annual cycle visible in the monthly profile.`,
  `2. Adjust for hour of day using the hourly profile.`,
  `3. Stay within plausible indoor ranges (AC-regulated room).`,
  `4. Output ONLY the JSON object. Nothing else.`,
].join("\n");

// Pass everything the response parser will need to stitch the final output.
return {
  json: {
    ...item,
    llm_input: { system, user },
    _context: {
      date_iso: target.toISOString(),
      room_id: room,
      model_data_range: model.data_range,
      model_trained_at: model.trained_at,
      extrapolation_days: daysPast,
    },
  },
};

// Process data and prepare results
const item = $input.item.json;

// --- Find the LLM's text response in whichever field it lives in ---
function findText(o) {
  if (!o) return null;
  if (typeof o === "string") return o;
  if (Array.isArray(o.content) && o.content[0] && o.content[0].text) return o.content[0].text;
  if (typeof o.output === "string") return o.output;
  if (o.message && typeof o.message.content === "string") return o.message.content;
  if (Array.isArray(o.choices) && o.choices[0] && o.choices[0].message) return o.choices[0].message.content;
  if (typeof o.text === "string")     return o.text;
  if (typeof o.response === "string") return o.response;
  if (typeof o.content === "string")  return o.content;
  return null;
}

const raw = findText(item) || findText(item.data) || findText(item.body);
if (!raw) {
  throw new Error(
    "Could not find the LLM's text response. Got keys: " + Object.keys(item).join(", ") +
    ". Adjust the parser if your LLM node emits a different shape."
  );
}

// --- Extract the JSON object from the response ---
// The model was asked to output pure JSON, but LLMs sometimes wrap it in
// markdown fences or add a prefix. Be forgiving.
function extractJson(text) {
  // Strip common markdown fences
  let s = text.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // If the response starts cleanly with a JSON object, parse directly.
  if (s.startsWith("{")) {
    try { return JSON.parse(s); } catch (_) { /* fall through */ }
  }

  // Otherwise find the first {...} block and try that.
  const start = s.indexOf("{");
  const end   = s.lastIndexOf("}");
  if (start !== -1 && end > start) {
    try { return JSON.parse(s.slice(start, end + 1)); } catch (_) {}
  }
  throw new Error("Could not parse JSON from LLM output. Raw: " + text.slice(0, 200));
}

const parsed = extractJson(raw);

// --- Sanity-check and coerce ---
const temp = Number(parsed.temperature);
const hum  = Number(parsed.humidity);
if (!Number.isFinite(temp) || !Number.isFinite(hum)) {
  throw new Error(`LLM returned non-numeric values: temperature=${parsed.temperature}, humidity=${parsed.humidity}`);
}
if (temp < 0 || temp > 50)  throw new Error(`LLM temperature out of plausible range: ${temp}°C`);
if (hum  < 0 || hum  > 100) throw new Error(`LLM humidity out of plausible range: ${hum}%`);

// --- Pull through the context we stashed in the prompt-builder ---
// The AI Agent node strips arbitrary fields from the item, so we can't rely
// on `item._context`. Reach back to the Build Prompt node directly.
let ctx = item._context;
if (!ctx || ctx.room_id == null) {
  try {
    ctx = $('Generate Prediction Prompt').item.json._context;
  } catch (_) {
    ctx = {};
  }
}
if (!ctx || ctx.room_id == null) {
  throw new Error(
    "Could not find the request context (date/room_id). The AI Agent node " +
    "stripped it from the item, and the Build Prompt node was not reachable. " +
    "Check that the Build Prompt node is named exactly 'Build Prompt'."
  );
}

return {
  json: {
    prediction: {
      temperature: Number(temp.toFixed(2)),
      humidity:    Number(hum.toFixed(2)),
      room_id: ctx.room_id,
      date: ctx.date_iso,
      model_trained_at: ctx.model_trained_at,
      model_data_range: ctx.model_data_range,
      extrapolation_days: ctx.extrapolation_days,
      source: "llm",
      reasoning: typeof parsed.reasoning === "string" ? parsed.reasoning : null,
    },
  },
};

// BUILD MONTH-AWARE REALISTIC ANOMALY PROMPT
// Run Once for Each Item

function mean(arr) {
  return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

const item = $json;
const prediction = item.prediction || item;

const predictedTemp = Number(prediction.temperature);
const predictedHum = Number(prediction.humidity);

const roomId = String(prediction.room_id);
const targetDate = new Date(prediction.date);
const targetMonth = targetDate.getMonth() + 1;

// Get historical rows from Google Sheet
const historicalRows = $("Load Historical Dataset").all();

// Same room + same month
let filteredRows = historicalRows.filter(r => {
  const rowRoom = String(r.json.room_id) === roomId;
  const rowDate = new Date(r.json.timestamp);
  const rowMonth = rowDate.getMonth() + 1;
  return rowRoom && rowMonth === targetMonth;
});

// Fallback = same room all year
if (filteredRows.length < 20) {
  filteredRows = historicalRows.filter(r => String(r.json.room_id) === roomId);
}

// Arrays
const temps = filteredRows
  .map(r => Number(r.json.temperature))
  .filter(Number.isFinite);

const hums = filteredRows
  .map(r => Number(r.json.humidity))
  .filter(Number.isFinite);

// Means
const tempMean = temps.length ? mean(temps) : 22;
const humMean = hums.length ? mean(hums) : 55;

// UAE realistic indoor monthly comfort thresholds
const comfortMap = {
  1:  { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  2:  { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  3:  { tLow: 22, tHigh: 24, hLow: 40, hHigh: 65 },
  4:  { tLow: 22, tHigh: 25, hLow: 40, hHigh: 68 },
  5:  { tLow: 20, tHigh: 23, hLow: 45, hHigh: 70 },
  6:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 72 },
  7:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 75 },
  8:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 75 },
  9:  { tLow: 20, tHigh: 23, hLow: 45, hHigh: 72 },
  10: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 68 },
  11: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  12: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 }
};

const c = comfortMap[targetMonth];

// Small historical adjustment only
const tempAdj = Math.max(-0.5, Math.min(0.5, tempMean - ((c.tLow + c.tHigh) / 2)));
const humAdj = Math.max(-3, Math.min(3, humMean - ((c.hLow + c.hHigh) / 2)));

const tempLower = Number((c.tLow + tempAdj).toFixed(1));
const tempUpper = Number((c.tHigh + tempAdj).toFixed(1));
const humLower = Number((c.hLow + humAdj).toFixed(1));
const humUpper = Number((c.hHigh + humAdj).toFixed(1));

// LLM prompt
const system = `
You are an anomaly detection agent.
Use the thresholds below.
Return ONLY valid JSON.
No explanation.

Format:
{
  "temperature_status": "Normal",
  "humidity_status": "Normal"
}
`;

const user = `
Predicted values:
Temperature = ${predictedTemp}
Humidity = ${predictedHum}

Room = ${roomId}
Target month = ${targetMonth}

Thresholds:
Temperature lower threshold = ${tempLower}
Temperature upper threshold = ${tempUpper}

Humidity lower threshold = ${humLower}
Humidity upper threshold = ${humUpper}

Rules:
If temperature > upper => High Anomaly
If temperature < lower => Low Anomaly
Else => Normal

If humidity > upper => High Anomaly
If humidity < lower => Low Anomaly
Else => Normal
`;

return {
  json: {
    prediction,

    temp_lower: tempLower,
    temp_upper: tempUpper,
    hum_lower: humLower,
    hum_upper: humUpper,

    temp_mean: Number(tempMean.toFixed(1)),
    hum_mean: Number(humMean.toFixed(1)),

    threshold_month: targetMonth,
    threshold_samples: filteredRows.length,

    anomaly_input: {
      system,
      user
    },

    _anomaly_context: {
      temp_lower: tempLower,
      temp_upper: tempUpper,
      hum_lower: humLower,
      hum_upper: humUpper,
      threshold_month: targetMonth
    }
  }
};

// Process data and prepare results
const raw =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message?.content ||
  JSON.stringify($json);

let cleaned = String(raw)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

const anomaly = JSON.parse(cleaned);

// IMPORTANT: use exact node name
const previous = $("Generate Anomaly Prompt").item.json;

const prediction = previous.prediction;
const ctx = previous._anomaly_context || {};

return {
  json: {
    prediction: {
      ...prediction,

      temperature_status: anomaly.temperature_status || "Normal",
      humidity_status: anomaly.humidity_status || "Normal",

      temp_lower: ctx.temp_lower,
      temp_upper: ctx.temp_upper,
      hum_lower: ctx.hum_lower,
      hum_upper: ctx.hum_upper,
      temp_mean: ctx.temp_mean,
      hum_mean: ctx.hum_mean,
      threshold_month: ctx.threshold_month,
      threshold_samples: ctx.threshold_samples,

      _backendBadge: "llm"
    }
  }
};

// Process data and prepare results
const p = $json.prediction || $json;
const idealTemp = Number(p.temp_mean || 22).toFixed(1);
const idealHum = Number(p.hum_mean || 55).toFixed(1);

const prompt = `
You are the Smart Building Recommendation Agent.

Analyze the final prediction and anomaly detection result.

Prediction Data:
${JSON.stringify(p, null, 2)}

Rules:
1. Target temperature = ${idealTemp}°C
2. Target humidity = ${idealHum}%
3. If temperature_status is High Anomaly:
   recommend decreasing temperature toward target.
4. If temperature_status is Low Anomaly:
   recommend increasing temperature toward target.
5. If humidity_status is High Anomaly:
   recommend decreasing humidity using ventilation/dehumidification.
6. If humidity_status is Low Anomaly:
   recommend increasing humidity for comfort.
7. If both are Normal:
   recommend maintaining current settings.
8. Return JSON only.
9. No markdown.

Return exactly:

{
  "recommendation": "...",
  "recommended_temperature": ${idealTemp},
  "recommended_humidity": ${idealHum}
}
`;

return {
  json: {
    prediction: p,
    chatInput: prompt
  }
};

// Process data and prepare results
const raw =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message?.content ||
  "";

let cleaned = String(raw)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let rec;

try {
  rec = JSON.parse(cleaned);
} catch (e) {
  rec = {
    recommendation: cleaned || "Conditions analyzed. Maintain system settings unless abnormal readings continue.",
    recommended_temperature: $("Generate Recommendation Prompt").item.json.prediction.temp_mean || 22,
    recommended_humidity: $("Generate Recommendation Prompt").item.json.prediction.hum_mean || 55
  };
}

const prediction = $("Generate Recommendation Prompt").item.json.prediction;

return {
  json: {
    prediction: {
      ...prediction,
      recommendation: rec.recommendation,
      recommended_temperature: rec.recommended_temperature,
      recommended_humidity: rec.recommended_humidity,
      _backendBadge: "llm"
    }
  }
};

