  const a = $("Generate Anomaly Prompt").item.json;
  const p = a.prediction || {};

  return {
    temperature: Number(p.temperature ?? 22),
    humidity: Number(p.humidity ?? 55),
    room_id: Number(p.room_id ?? 2),
    date: p.date || new Date().toISOString(),

    recommendation: $json.recommendation || "Conditions are normal. Maintain current settings.",
